class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        vals = [ord(c) - ord('a') for c in s]

        # prev2: DP for length L-2, prev1: DP for length L-1.
        prev2 = []
        prev1 = [[1] * (k + 1) for _ in range(n)]

        for length in range(2, n + 1):
            curr = []
            for i in range(n - length + 1):
                j = i + length - 1

                diff = abs(vals[i] - vals[j])
                cost = min(diff, 26 - diff)

                left = prev1[i + 1]   # dp[i+1][j]
                right = prev1[i]      # dp[i][j-1]
                mid = prev2[i + 1] if length > 2 else None

                best = [0] * (k + 1)
                for budget in range(k + 1):
                    ans = left[budget] if left[budget] > right[budget] else right[budget]

                    if cost <= budget:
                        inside = 0 if length == 2 else mid[budget - cost]
                        paired = inside + 2
                        if paired > ans:
                            ans = paired

                    best[budget] = ans

                curr.append(best)

            prev2, prev1 = prev1, curr

        return prev1[0][k]
